    GetCostForecastRequest.add_member(:filter, Smithy::Schema::Shapes::ShapeRef.new(shape: Expression, location_name: 'Filter', traits: {"smithy.api#documentation" => "<p>The filters that you want to use to filter your forecast. The\n        <code>GetCostForecast</code> API supports filtering by the following dimensions:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>AZ</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>INSTANCE_TYPE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>LINKED_ACCOUNT</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>OPERATION</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>PURCHASE_TYPE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>REGION</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>SERVICE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>USAGE_TYPE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>USAGE_TYPE_GROUP</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>RECORD_TYPE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>OPERATING_SYSTEM</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>TENANCY</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>SCOPE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>PLATFORM</code>\n      