    GetDimensionValuesResponse.type = Types::GetDimensionValuesResponse
    GetReservationCoverageRequest.add_member(:time_period, Smithy::Schema::Shapes::ShapeRef.new(shape: DateInterval, location_name: 'TimePeriod', traits: {"smithy.api#documentation" => "<p>The start and end dates of the period that you want to retrieve data about reservation\n      coverage for. You can retrieve data for a maximum of 13 months: the last 12 months and the\n      current month. The start date is inclusive, but the end date is exclusive. For example, if\n        <code>start</code> is <code>2017-01-01</code> and <code>end</code> is\n        <code>2017-05-01</code>, then the cost and usage data is retrieved from\n        <code>2017-01-01</code> up to and including <code>2017-04-30</code> but not including\n        <code>2017-05-01</code>. </p>", "smithy.api#required" => {}}))
    GetReservationCoverageRequest.add_member(:group_by, Smithy::Schema::Shapes::ShapeRef.new(shape: GroupDefinitions, location_name: 'GroupBy', traits: {"smithy.api#documentation" => "<p>You can group the data by the following attributes:</p>\n         <ul>\n            <li>\n               <p>AZ</p>\n            </li>\n            <li>\n               <p>CACHE_ENGINE</p>\n            </li>\n            <li>\n               <p>DATABASE_ENGINE</p>\n            </li>\n            <li>\n               <p>DEPLOYMENT_OPTION</p>\n            </li>\n            <li>\n               <p>INSTANCE_TYPE</p>\n            </li>\n            <li>\n               <p>INVOICING_ENTITY</p>\n            </li>\n            <li>\n               <p>LINKED_ACCOUNT</p>\n            </li>\n            <li>\n               <p>OPERATING_SYSTEM</p>\n            </li>\n            <li>\n               <p>PLATFORM</p>\n            </li>\n            <li>\n               <p>REGION</p>\n            </li>\n            <li>\n               <p>TENANCY</p>\n            </li>\n         </ul>"}))
    GetReservationCoverageRequest.add_member(:granularity, Smithy::Schema::Shapes::ShapeRef.new(shape: Granularity, location_name: 'Granularity', traits: {"smithy.api#documentation" => "<p>The granularity of the Amazon Web Services cost data for the reservation. Valid values\n      are <code>MONTHLY</code> and <code>DAILY</code>.</p>\n         <p>If <code>GroupBy</code> is set, <code>Granularity</code> can't be set. If\n        <code>Granularity</code> isn't set, the response object doesn't include\n        <code>Granularity</code>, either <code>MONTHLY</code> or <code>DAILY</code>.</p>\n         <p>The <code>GetReservationCoverage</code> operation supports only <code>DAILY</code> and\n        <code>MONTHLY</code> granularities.</p>"}))
    GetReservationCoverageRequest.add_member(:filter, Smithy::Schema::Shapes::ShapeRef.new(shape: Expression, location_name: 'Filter', traits: {"smithy.api#documentation" => "<p>Filters utilization data by dimensions. You can filter by the following\n      dimensions:</p>\n         <ul>\n            <li>\n               <p>AZ</p>\n            </li>\n            <li>\n               <p>CACHE_ENGINE</p>\n            </li>\n            <li>\n               <p>DATABASE_ENGINE</p>\n            </li>\n            <li>\n               <p>DEPLOYMENT_OPTION</p>\n            </li>\n            <li>\n               <p>INSTANCE_TYPE</p>\n            </li>\n            <li>\n               <p>LINKED_ACCOUNT</p>\n            </li>\n            <li>\n               <p>OPERATING_SYSTEM</p>\n            </li>\n            <li>\n               <p>PLATFORM</p>\n            </li>\n            <li>\n               <p>REGION</p>\n            </li>\n            <li>\n               <p>SERVICE</p>\n            </li>\n            <li>\n               <p>TAG</p>\n            </li>\n            <li>\n               <p>TENANCY</p>\n            </li>\n         </ul>\n         <p>\n            <code>GetReservationCoverage</code> uses the same <a href=\"https://docs.aws.amazon.com/aws-cost-management/latest/APIReference/API_Expression.html\">Expression</a> object\n      as the other operations, but only <code>AND</code> is supported among each dimension. You can\n      nest only one level deep. If there are multiple values for a dimension, they are OR'd\n      together.</p>\n         <p>If you don't provide a <code>SERVICE</code> filter, Cost Explorer defaults to\n      EC2.</p>\n         <p>Cost category is also supported.</p>"}))
    GetReservationCoverageRequest.add_member(:metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricNames, location_name: 'Metrics', traits: {"smithy.api#documentation" => "<p>The measurement that you want your reservation coverage reported in.</p>\n         <p>Valid values are <code>Hour</code>, <code>Unit</code>, and <code>Cost</code>. You can use\n      multiple values in a request.</p>"}))
    GetReservationCoverageRequest.add_member(:next_page_token, Smithy::Schema::Shapes::ShapeRef.new(shape: NextPageToken, location_name: 'NextPageToken', traits: {"smithy.api#documentation" => "<p>The token to retrieve the next set of results. Amazon Web Services provides the token\n      when the response from a previous call has more results than the maximum page size.</p>"}))
    GetReservationCoverageRequest.add_member(:sort_by, Smithy::Schema::Shapes::ShapeRef.new(shape: SortDefinition, location_name: 'SortBy', traits: {"smithy.api#documentation" => "<p>The value by which you want to sort the data.</p>\n         <p>The following values are supported for <code>Key</code>:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>OnDemandCost</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>CoverageHoursPercentage</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>OnDemandHours</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ReservedHours</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>TotalRunningHours</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>CoverageNormalizedUnitsPercentage</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>OnDemandNormalizedUnits</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ReservedNormalizedUnits</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>TotalRunningNormalizedUnits</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Time</code>\n               </p>\n            </li>\n         </ul>\n         <p>Supported values for <code>SortOrder</code> are <code>ASCENDING</code> or\n        <code>DESCENDING</code>.</p>"}))
    GetReservationCoverageRequest.add_member(:max_results, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxResults, location_name: 'MaxResults', traits: {"smithy.api#documentation" => "<p>The maximum number of objects that you returned for this request. If more objects are\n      available, in the response, Amazon Web Services provides a NextPageToken value that you can use\n      in a subsequent call to get the next batch of objects.</p>"}))
